const Home = () => {
  return (
    <main>
      <NavBar />
      <Hero />
      <LiveStatus />
      <ImpactStats /> 
      <FeatureCards />
      <HowItWorks />
      <Roadmap />
      <TechStack />
      <ContactForm />
      <Footer />
